#!/bin/bash
# ID29 seq=184: deploy additive independent replacement-verifier payload by exact hash.
set -eo pipefail

ROOT=/data1/home/sunyiq/nearing2022_da
source ~/miniconda3/etc/profile.d/conda.sh
conda activate nh_final
cd "$ROOT"

python - <<'PY'
import base64
import hashlib
import json
import os
from pathlib import Path
import shutil
import tempfile

root = Path("/data1/home/sunyiq/nearing2022_da").resolve()
payloads = [
    {
        "path": "results/29_nearing2022_da_ar/formal_closure/warmup_target_paired_retraining_protocol.json",
        "bytes": 7266,
        "sha256": "16bdf57bcbf3afd335e91107bc908330e86ac7fa20db60cbf54ee30b1ab321c1",
        "base64": "".join([
            "",
            "",
            "",
        ]),
    },
    {
        "path": "results/29_nearing2022_da_ar/formal_closure/warmup_target_paired_retraining_protocol_amendment_01.json",
        "bytes": 3779,
        "sha256": "a21bae28a26f5797e96232628fdc139f5ffd1e54e31ee2032a7805acb0785ef5",
        "base64": "".join([
            "",
            "",
        ]),
    },
    {
        "path": "src/29_nearing2022_da_ar/scripts/verify_warmup_target_replacement_chain.py",
        "bytes": 29458,
        "sha256": "0bcabc96f9e702f2317464f1f0123c29d49d5f7f0f972a10ea3e01bbf18fe987",
        "base64": "".join([
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
        ]),
    },
    {
        "path": "test/test_nearing2022_replacement_chain_verifier.py",
        "bytes": 19042,
        "sha256": "2da179cb1ef02b0697472fd273bd61ffad98ecb5790e5b5f2dce6032e478dad6",
        "base64": "".join([
            "",
            "",
            "",
            "",
            "",
            "",
            "",
        ]),
    },
    {
        "path": "results/29_nearing2022_da_ar/formal_closure/warmup_target_replacement_independent_verifier_preflight_20260811.json",
        "bytes": 4819,
        "sha256": "80bf711779dcef12b991be7b53359dfcdc550e3fbf049720ec5bc24b01620b0f",
        "base64": "".join([
            "",
            "",
        ]),
    },
    {
        "path": "results/29_nearing2022_da_ar/formal_closure/warmup_target_replacement_verifier_prerequisite_audit_20260811.json",
        "bytes": 4392,
        "sha256": "e4211d680611e34d85c9b93ebcb8c90f5b05fa7425e0e6f0830ad6971260fa8f",
        "base64": "".join([
            "",
            "",
        ]),
    }
]
stage_parent = root / "results/29_nearing2022_da_ar/formal_closure"
if not stage_parent.is_dir():
    raise SystemExit(f"missing staging parent: {stage_parent}")
stage = Path(tempfile.mkdtemp(prefix=".seq184_verifier_payload_", dir=stage_parent))
entries = []
pending = []
try:
    for index, item in enumerate(payloads):
        rel = Path(item["path"])
        if rel.is_absolute() or ".." in rel.parts:
            raise SystemExit(f"unsafe payload path: {rel}")
        target = (root / rel).resolve()
        target.relative_to(root)
        data = base64.b64decode(item["base64"], validate=True)
        actual_hash = hashlib.sha256(data).hexdigest()
        if len(data) != item["bytes"] or actual_hash != item["sha256"]:
            raise SystemExit(f"embedded payload mismatch: {rel}")
        if not target.parent.is_dir() or target.parent.is_symlink():
            raise SystemExit(f"unsafe or missing target parent: {target.parent}")
        if target.exists() or target.is_symlink():
            if target.is_symlink() or not target.is_file():
                raise SystemExit(f"unsafe existing target: {rel}")
            existing = target.read_bytes()
            existing_hash = hashlib.sha256(existing).hexdigest()
            if len(existing) != item["bytes"] or existing_hash != item["sha256"]:
                raise SystemExit(
                    f"refusing different existing target: {rel} "
                    f"bytes={len(existing)} sha256={existing_hash}"
                )
            entries.append({
                "path": rel.as_posix(),
                "bytes": len(existing),
                "sha256": existing_hash,
                "action": "already_matching",
            })
            continue
        staged = stage / f"{index:02d}.payload"
        with staged.open("xb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(staged, 0o644)
        pending.append((rel, target, staged, item))

    for rel, target, staged, item in pending:
        os.link(staged, target)
        deployed = target.read_bytes()
        deployed_hash = hashlib.sha256(deployed).hexdigest()
        if len(deployed) != item["bytes"] or deployed_hash != item["sha256"]:
            raise SystemExit(f"post-deployment mismatch: {rel}")
        entries.append({
            "path": rel.as_posix(),
            "bytes": len(deployed),
            "sha256": deployed_hash,
            "action": "deployed_additively",
        })

    by_path = {entry["path"]: entry for entry in entries}
    ordered = [by_path[item["path"]] for item in payloads]
    receipt = {
        "schema": "nearing2022-replacement-verifier-payload-deployment-v1",
        "mailbox_seq": 184,
        "status": "exact_payload_present",
        "root": str(root),
        "files": len(ordered),
        "deployed": sum(entry["action"] == "deployed_additively" for entry in ordered),
        "already_matching": sum(entry["action"] == "already_matching" for entry in ordered),
        "entries": ordered,
        "paired_preparer_modified": False,
        "paired_runner_modified": False,
        "registered_matrix_modified": False,
        "slurm_job_modified_or_submitted": False,
    }
    print("=== PAYLOAD DEPLOYMENT RECEIPT ===")
    print(json.dumps(receipt, sort_keys=True))
finally:
    shutil.rmtree(stage)
PY

echo "=== REPLACEMENT JOBS REMAIN UNCHANGED ==="
for job in 202510 202511; do
  scontrol show job -o "$job" | sed -n 's/.*JobId=\([^ ]*\).*JobState=\([^ ]*\).*Reason=\([^ ]*\).*Dependency=\([^ ]*\).*/\1|\2|\3|\4/p'
done
echo "registered_matrix_modified=false"
echo "paired_runner_modified=false"
echo "slurm_job_modified_or_submitted=false"
